export const faqParity:Record<ParityLang,FAQData>={
de:{home:'Startseite',page:'FAQ',eyebrow:'Vor und während Ihres Aufenthalts',title:'Häufig gestellte Fragen',subtitle:'Check-in, Check-out, Gepäck, Parkplatz, Kinder, Haustiere und praktische Informationen für Ihren Aufenthalt.',groupNote:'Anfragen, die von der Verfügbarkeit abhängen, müssen direkt mit uns vereinbart werden.',groups:[
{title:'Anreise und Check-in',items:[['Wann ist der Check-in möglich?','Die Check-in-Zeit wird vor der Anreise vereinbart. Bitte teilen Sie uns Ihre voraussichtliche Ankunftszeit mit und informieren Sie uns etwa eine Stunde vorher erneut.'],['Ist ein sehr später Check-in möglich?','Das hängt von der Unterkunft, der Uhrzeit und den vorher getroffenen Vereinbarungen ab. Kontaktieren Sie uns vor der Buchung, wenn Sie sehr spät anreisen.'],['Gibt es Self Check-in?','Self Check-in mit elektronischer Tastatur ist nur in Dimora Castelli möglich, wenn dies vorab vereinbart wurde. Rossi Apartment sieht normalerweise eine persönliche Begrüßung vor.'],['Kann ich früher einchecken?','Wir prüfen dies je nach Abreise der vorherigen Gäste und Reinigungszeit. Eine Garantie im Voraus ist nicht möglich.']]},
{title:'Abreise und Gepäck',items:[['Wann ist der Check-out?','Der Check-out erfolgt bis 10:00 Uhr, sofern nichts anderes vereinbart wurde.'],['Ist ein später Check-out möglich?','Wir können dies je nach nächsten Anreisen und Reinigungsplan prüfen.'],['Gibt es eine Gepäckaufbewahrung?','Wenn es unser Tagesablauf erlaubt, können wir Gepäck vor dem Check-in oder nach dem Check-out kostenlos aufbewahren. Bitte fragen Sie uns nach der Verfügbarkeit.'],['Kann ich das Auto nach dem Check-out stehen lassen?','Das hängt von den nächsten Anreisen und der Parkplatzverfügbarkeit ab. Fragen Sie uns vor der Abreise; wir versuchen es möglich zu machen, können es aber nicht immer garantieren.']]},
{title:'Parken und Mobilität',items:[['Ist der Parkplatz kostenlos?','Ja. Beide Apartments verfügen über einen kostenlosen privaten Parkplatz gemäß den jeweiligen Bedingungen der Unterkunft.'],['Brauche ich ein Auto für Venedig?','Nein. Wir empfehlen, das Auto stehen zu lassen und Bus oder Zug zu nutzen.'],['Wo finde ich Informationen zu Bus, Zug und Tickets?','Auf der Seite „Nach Venedig“ finden Sie Informationen zur Anreise, zu Flughäfen, Bahnhof und Verbindungen nach Venedig.']]},
{title:'Familien und Haustiere',items:[['Gibt es ein Baby- oder Kinderbett?','Ja. Baby- oder Kinderbett mit Bettwäsche ist in beiden Apartments auf Anfrage kostenlos verfügbar.'],['Sind die Apartments haustierfreundlich?','Ja. Wir können Hundebett und Näpfe bereitstellen. Bitte informieren Sie uns vor der Anreise über Ihr Haustier.'],['Gibt es Zuschläge für Kinder oder Haustiere?','Etwaige Bedingungen werden vor der Buchung klar mitgeteilt.']]},
{title:'Dokumente und Aufenthalt',items:[['Benötigen Sie Ausweise aller Gäste?','Ja. Nach italienischem Recht müssen alle Gäste, auch Minderjährige, registriert werden.'],['Wie wird die Kurtaxe gehandhabt?','Die Kurtaxe richtet sich nach den zum Zeitpunkt des Aufenthalts geltenden Regeln der Stadt Venedig. Beträge und Ausnahmen können sich ändern.'],['Kann ich eine bestimmte Bettenaufteilung anfragen?','Wenn möglich, bitten wir Sie, uns Ihre gewünschte Bettenkonfiguration vor der Anreise mitzuteilen.']]}
],ctaTitle:'Noch eine Frage?',ctaText:'Schreiben Sie uns vor der Buchung. Wir klären gerne alle Details im Voraus.',ctaLabel:'Auf WhatsApp schreiben',ctaMessage:'Hallo, ich habe eine Frage zu einem Aufenthalt bei Marghera Venice Apartments. '},
fr:{home:'Accueil',page:'FAQ',eyebrow:'Avant et pendant votre séjour',title:'Questions fréquentes',subtitle:'Check-in, check-out, bagages, parking, enfants, animaux et informations pratiques pour votre séjour.',groupNote:'Les demandes dépendant des disponibilités doivent être convenues directement avec nous.',groups:[
{title:'Arrivée et check-in',items:[['À quelle heure peut-on faire le check-in ?','L’heure de check-in est convenue avant l’arrivée. Nous demandons aux voyageurs de nous communiquer leur heure prévue et de nous prévenir environ une heure avant.'],['Peut-on arriver très tard dans la nuit ?','Cela dépend de l’appartement, de l’horaire et des accords pris avant l’arrivée. Contactez-nous avant de réserver si vous prévoyez une arrivée très tardive.'],['Le self check-in est-il disponible ?','Le self check-in par clavier électronique est disponible uniquement à Dimora Castelli lorsqu’il est convenu à l’avance. Rossi Apartment prévoit normalement un accueil en personne.'],['Peut-on demander un check-in anticipé ?','Nous pouvons l’évaluer selon le départ des voyageurs précédents et le temps de ménage. Il ne peut pas être garanti à l’avance.']]},
{title:'Départ et bagages',items:[['À quelle heure est le check-out ?','Le check-out est prévu avant 10 h, sauf accord différent.'],['Peut-on demander un check-out tardif ?','Nous pouvons l’évaluer selon les arrivées suivantes et l’organisation du ménage.'],['Peut-on laisser les bagages ?','Lorsque notre organisation le permet, nous pouvons garder gratuitement les bagages avant le check-in ou après le check-out. Contactez-nous pour vérifier la disponibilité.'],['Puis-je laisser la voiture après le check-out ?','Cela dépend des arrivées suivantes et de la disponibilité du parking. Demandez-nous avant votre départ : nous ferons notre possible, sans pouvoir toujours le garantir.']]},
{title:'Parking et déplacements',items:[['Le parking est-il gratuit ?','Oui. Les deux appartements disposent d’un parking privé gratuit selon les modalités propres à chaque logement.'],['Faut-il une voiture pour visiter Venise ?','Non. Nous conseillons de laisser la voiture au parking et d’utiliser le bus ou le train.'],['Où trouver les informations sur les bus, trains et billets ?','La page « Rejoindre Venise » regroupe les informations depuis les aéroports, la gare et pour rejoindre Venise.']]},
{title:'Familles et animaux',items:[['Fournissez-vous un lit bébé ou enfant ?','Oui. Un lit bébé ou enfant avec linge est disponible gratuitement sur demande dans les deux appartements.'],['Les appartements acceptent-ils les animaux ?','Oui. Nous pouvons fournir un couchage et des gamelles. Merci de nous signaler votre animal avant l’arrivée.'],['Y a-t-il des frais supplémentaires pour les enfants ou animaux ?','Les éventuelles conditions sont communiquées clairement avant la réservation.']]},
{title:'Documents et séjour',items:[['Faut-il les documents de tous les voyageurs ?','Oui. La réglementation italienne impose l’enregistrement de toutes les personnes hébergées, y compris les mineurs.'],['Comment fonctionne la taxe de séjour ?','La taxe est appliquée selon les règles de la Ville de Venise en vigueur au moment du séjour. Les montants et exemptions peuvent évoluer.'],['Peut-on choisir la disposition des lits ?','Lorsque cela est possible, nous demandons aux voyageurs de communiquer la configuration souhaitée avant l’arrivée.']]}
],ctaTitle:'Encore une question ?',ctaText:'Écrivez-nous avant de réserver : nous serons heureux de clarifier chaque détail.',ctaLabel:'Nous écrire sur WhatsApp',ctaMessage:'Bonjour, j’ai une question concernant un séjour à Marghera Venice Apartments. '},
es:{home:'Inicio',page:'FAQ',eyebrow:'Antes y durante tu estancia',title:'Preguntas frecuentes',subtitle:'Check-in, check-out, equipaje, aparcamiento, niños, mascotas e información práctica para tu estancia.',groupNote:'Las solicitudes sujetas a disponibilidad deben acordarse directamente con nosotros.',groups:[
{title:'Llegada y check-in',items:[['¿A qué hora se puede hacer el check-in?','La hora se acuerda antes de la llegada. Pedimos a los huéspedes que nos comuniquen su hora prevista y que nos avisen aproximadamente una hora antes.'],['¿Se puede llegar muy tarde por la noche?','Depende del apartamento, la hora y los acuerdos previos. Contáctanos antes de reservar si prevés llegar muy tarde.'],['¿Hay self check-in?','El self check-in con teclado electrónico solo está disponible en Dimora Castelli cuando se acuerda previamente. Rossi Apartment normalmente incluye recepción en persona.'],['¿Puedo pedir un check-in anticipado?','Podemos valorarlo según la salida de los huéspedes anteriores y el tiempo de limpieza. No se puede garantizar con antelación.']]},
{title:'Salida y equipaje',items:[['¿A qué hora es el check-out?','El check-out es antes de las 10:00, salvo acuerdo diferente.'],['¿Puedo pedir un check-out tardío?','Podemos valorarlo según las siguientes llegadas y la organización de la limpieza.'],['¿Hay consigna para el equipaje?','Cuando nuestra organización lo permite, podemos guardar el equipaje gratis antes del check-in o después del check-out. Contáctanos para comprobar disponibilidad.'],['¿Puedo dejar el coche después del check-out?','Depende de las siguientes llegadas y de la disponibilidad del aparcamiento. Pregúntanos antes de salir; haremos lo posible, pero no siempre podemos garantizarlo.']]},
{title:'Aparcamiento y movilidad',items:[['¿El aparcamiento es gratuito?','Sí. Ambos apartamentos disponen de aparcamiento privado gratuito según las condiciones específicas de cada alojamiento.'],['¿Necesito coche para visitar Venecia?','No. Recomendamos dejar el coche aparcado y utilizar autobús o tren.'],['¿Dónde encuentro información sobre autobuses, trenes y billetes?','En la página «Cómo llegar a Venecia» encontrarás indicaciones desde aeropuertos, estación y conexiones con Venecia.']]},
{title:'Familias y mascotas',items:[['¿Hay cuna o cama infantil?','Sí. Cuna o cama infantil con ropa de cama está disponible gratis bajo petición en ambos apartamentos.'],['¿Se admiten mascotas?','Sí. Podemos proporcionar cama y cuencos. Avísanos de la presencia de tu mascota antes de llegar.'],['¿Hay suplementos por niños o mascotas?','Las posibles condiciones se comunican claramente antes de reservar.']]},
{title:'Documentos y estancia',items:[['¿Necesitáis documentos de todos los huéspedes?','Sí. La normativa italiana exige registrar a todas las personas alojadas, incluidos los menores.'],['¿Cómo funciona la tasa turística?','Se aplica según las normas del Ayuntamiento de Venecia vigentes durante la estancia. Importes y exenciones pueden cambiar.'],['¿Puedo elegir la configuración de las camas?','Cuando sea posible, pedimos que nos indiques antes de la llegada la configuración de camas que prefieres.']]}
],ctaTitle:'¿Te queda alguna pregunta?',ctaText:'Escríbenos antes de reservar: estaremos encantados de aclarar todos los detalles.',ctaLabel:'Escribir por WhatsApp',ctaMessage:'Hola, tengo una pregunta sobre una estancia en Marghera Venice Apartments. '},
zh:{home:'首页',page:'常见问题',eyebrow:'入住前与入住期间',title:'常见问题',subtitle:'入住、退房、行李、停车、儿童、宠物以及住宿期间的实用信息。',groupNote:'如相关服务取决于当天安排，请提前直接与我们确认。',groups:[
{title:'抵达与入住',items:[['几点可以入住？','入住时间会在抵达前确认。请提前告诉我们预计到达时间，并在到达前约一小时再次通知。'],['可以深夜入住吗？','这取决于公寓、具体时间以及事先约定。如果预计很晚抵达，请在预订前先联系我们。'],['可以自助入住吗？','Dimora Castelli 可在提前约定后使用电子键盘自助入住；Rossi Apartment 通常由我们当面接待。'],['可以提前入住吗？','我们会根据前一位客人的退房和清洁安排评估，但无法提前保证。']]},
{title:'退房与行李',items:[['几点退房？','除非另有约定，请在 10:00 前退房。'],['可以延迟退房吗？','我们会根据下一批客人的抵达时间和清洁安排评估。'],['可以寄存行李吗？','如当天安排允许，我们可在入住前或退房后免费提供行李寄存。请提前联系我们确认。'],['退房后可以继续把车停在公寓吗？','这取决于之后的入住安排和停车位情况。请在离开前询问，我们会尽量安排，但不能始终保证。']]},
{title:'停车与交通',items:[['停车免费吗？','是的，两套公寓均提供免费私人停车位，具体以各住宿说明为准。'],['游览威尼斯需要开车吗？','不需要。我们建议把车留在公寓，乘公交或火车前往威尼斯。'],['在哪里查看公交、火车和车票信息？','“前往威尼斯”页面提供机场、火车站以及从马尔盖拉前往威尼斯的实用信息。']]},
{title:'家庭与宠物',items:[['提供婴儿床或儿童床吗？','是的，两套公寓均可按需免费提供婴儿床或儿童床及床品。'],['可以带宠物吗？','可以。我们可提供宠物垫和食水碗。请在抵达前告诉我们宠物情况。'],['儿童或宠物有额外费用吗？','如有适用条件，我们会在预订前清楚说明。']]},
{title:'证件与住宿',items:[['所有客人都需要提供证件吗？','需要。意大利法规要求登记所有入住人员，包括未成年人。'],['城市税如何收取？','城市税按照入住期间威尼斯市的现行规定执行，金额和减免条件可能变化。'],['可以选择床位组合吗？','如条件允许，请在抵达前告诉我们希望的床位配置。']]}
],ctaTitle:'还有其他问题？',ctaText:'预订前通过微信联系我们，我们会亲自为您确认每个细节。',ctaLabel:'微信联系我们',ctaMessage:''}
};

const commonVeniceIslands={de:[['Murano','Glaskunst, Werkstätten und ein angenehmer Spaziergang auf der Insel.','/images/murano-glass.webp'],['Burano','Bunte Häuser, Spitzentradition und unverwechselbare Ausblicke.','/images/burano-canale.webp'],['Lido','Strand, Fahrräder und eine entspanntere Seite der Lagune.','/images/lido-venezia-spiaggia.webp']],fr:[['Murano','Art du verre, ateliers et promenade agréable dans la lagune.','/images/murano-glass.webp'],['Burano','Maisons colorées, tradition de la dentelle et vues mémorables.','/images/burano-canale.webp'],['Lido','Plage, vélo et une facette plus détendue de la lagune.','/images/lido-venezia-spiaggia.webp']],es:[['Murano','Vidrio artístico, talleres y un agradable paseo por la isla.','/images/murano-glass.webp'],['Burano','Casas de colores, tradición del encaje y vistas inolvidables.','/images/burano-canale.webp'],['Lido','Playa, bicicleta y un lado más relajado de la laguna.','/images/lido-venezia-spiaggia.webp']],zh:[['Murano','玻璃艺术、工坊以及轻松的岛上散步。','/images/murano-glass.webp'],['Burano','彩色房屋、蕾丝传统与难忘的泻湖景色。','/images/burano-canale.webp'],['Lido','海滩、自行车以及更放松的泻湖体验。','/images/lido-venezia-spiaggia.webp']]} as const;
